import test from 'node:test';import assert from 'node:assert/strict';import {normalizeExpeditions,expeditionModes,expeditionBands,expeditionHash,expeditionSurface,expeditionCell,expeditionVisibleCells,expeditionChunkItems,expeditionEnter,expeditionPath,expeditionTravel,expeditionTick,expeditionToggleFlight,expeditionAction,expeditionView,expeditionGoal,expeditionInteract,expeditionPlace,expeditionJournal,expeditionSuitVisual} from '../src/expeditions.js';import {defaultJacc} from '../src/jacc-builder.js';
function run(s,limit=5000){let kinds=new Set();for(let i=0;i<limit;i++){const r=expeditionTick(s,.05),w=s.worlds[s.active];if(w.motion)kinds.add(w.motion.kind);if(r.arrived)return {r,kinds};if(!w.route.length&&!w.motion&&i>3)return {r,kinds};}throw Error('Travel did not finish: '+s.active);}
test('terrain streams deterministically over distant coordinates without allocating a map',()=>{for(const mode of Object.keys(expeditionModes)){const s=normalizeExpeditions({seed:42});expeditionEnter(s,mode);const w=s.worlds[mode],a=expeditionCell(w,mode,12345,mode==='farm'?-222:35);assert.deepEqual(a,expeditionCell(w,mode,12345,mode==='farm'?-222:35));assert.ok(expeditionVisibleCells(w,mode).length<=400);assert.ok(expeditionChunkItems(w,mode,-1234).length);assert.deepEqual(expeditionChunkItems(w,mode,1234),expeditionChunkItems(w,mode,1234));assert.notEqual(expeditionHash(42,123),expeditionHash(43,123));}assert.ok(!('tiles' in normalizeExpeditions().worlds.forest));});
test('all explorers can fly and fold boosters; unsupported walking has gravity while swimming is assisted',()=>{const s=normalizeExpeditions();expeditionEnter(s,'forest');const w=s.worlds.forest;w.x=20;w.y=200;w.fly=true;expeditionTick(s,.05);assert.equal(w.y,200);expeditionToggleFlight(s);for(let i=0;i<8;i++)expeditionTick(s,.05);assert.ok(w.y>200);assert.ok(w.vy>0);expeditionEnter(s,'ocean');const water=s.worlds.ocean,old=water.y;for(let i=0;i<20;i++)expeditionTick(s,.05);assert.equal(water.y,old);assert.equal(expeditionToggleFlight(s),false);const custom=defaultJacc(),copy=JSON.stringify(custom);assert.equal(expeditionSuitVisual(custom,true,'forest').parts.back,'both');assert.equal(expeditionSuitVisual(custom,false,'forest').parts.back,'thrusters');assert.equal(JSON.stringify(custom),copy);});
test('a tap routes through automatic tree climbing and supported hops without holding directions',()=>{for(const seed of [0,1,42,2063,0xffffffff]){const s=normalizeExpeditions({seed});expeditionEnter(s,'forest');const g=expeditionGoal(s),w=s.worlds.forest;assert.ok(expeditionPath(w,'forest',g.point).length);expeditionTravel(s,g.point,{item:g.item});const {r,kinds}=run(s);assert.equal(r.arrived.item.type,'seed');assert.ok(kinds.has('climb'));const result=expeditionInteract(s,g.item);assert.ok(result.effect.seed);assert.equal(w.mission,1);const pos={x:w.x,y:w.y};expeditionAction(s,{type:'goal'});run(s);assert.ok(w.y<14*40);assert.equal(w.fly,true);assert.equal(w.mission,2);assert.notDeepEqual({x:w.x,y:w.y},pos);}});
test('digging makes persistent passages and supports; fossils are sedimentary and the mantle stays solid rock',()=>{const s=normalizeExpeditions();expeditionEnter(s,'cave');const w=s.worlds.cave,g=expeditionGoal(s);expeditionTravel(s,g.point,{item:g.item});const {r}=run(s);assert.equal(r.arrived.item.type,'fossil');assert.ok(w.dug.length>20);const found=expeditionInteract(s,g.item);assert.equal(found.effect.material,'fossil');assert.equal(g.item.y/40<48,true);const before=w.dug.length;expeditionAction(s,{type:'band',index:4});assert.ok(w.y>=116*40);assert.ok(w.dug.length>=before);let mantle=0;for(let x=20;x<40;x++)if(expeditionCell(w,'cave',x,125).type==='mantle')mantle++;assert.ok(mantle>15);const saved=normalizeExpeditions(JSON.parse(JSON.stringify(s)));assert.deepEqual(saved.worlds.cave.dug,w.dug);assert.ok(expeditionCell(saved.worlds.cave,'cave',Math.floor(w.x/40),Math.floor((w.y-1)/40)).climb);});
test('the sky includes every atmospheric band and orbital exploration inside the thermosphere; water reaches the abyss',()=>{const s=normalizeExpeditions();expeditionEnter(s,'sky');const w=s.worlds.sky;assert.ok(w.fly);for(let i=0;i<expeditionBands.sky.length;i++){expeditionAction(s,{type:'band',index:i});expeditionTick(s,.05);assert.ok(w.bands.includes(i));}assert.match(expeditionBands.sky[1][0],/Thermosphere/);assert.match(expeditionBands.sky[1][3],/Orbit is motion/);expeditionEnter(s,'ocean');expeditionAction(s,{type:'band',index:3});expeditionTick(s,.05);assert.ok(s.worlds.ocean.bands.includes(3));assert.match(expeditionBands.ocean[3][0],/Abyss/);});
test('top-down farming uses owned seeds and visit-based stages rather than time or menus',()=>{const s=normalizeExpeditions();expeditionEnter(s,'farm');const w=s.worlds.farm,ctx={plants:[{id:'bean',name:'Bean',icon:'B'}]};expeditionAction(s,{type:'goal'},ctx);const {r}=run(s);assert.equal(r.arrived.kind,'plot');w.selectedPlot=r.arrived.key;expeditionAction(s,{type:'plant',seed:'unknown'},ctx);assert.equal(Object.keys(w.plots).length,0);expeditionAction(s,{type:'plant',seed:'bean'},ctx);const p=w.plots[w.selectedPlot];assert.equal(p.stage,0);expeditionAction(s,{type:'water'},ctx);for(let i=0;i<100;i++)expeditionTick(s,.05);assert.equal(p.stage,0);expeditionView(s,'plot',ctx);assert.equal(p.stage,0);for(let stage=1;stage<=3;stage++){expeditionEnter(s,'forest');expeditionEnter(s,'farm');assert.equal(p.stage,stage);if(stage<3)expeditionAction(s,{type:'water'},ctx);}const result=expeditionAction(s,{type:'harvest'},ctx);assert.equal(result.effect.harvest,'bean');assert.equal(w.mission,2);assert.ok(expeditionJournal(s,'experiments').some(e=>e.id==='exp-harvest-bean'));});
test('tap-built supports, platforms and ladders persist; removing an own platform allows a safe fall',()=>{const s=normalizeExpeditions();expeditionEnter(s,'forest');const w=s.worlds.forest;w.x=20;w.y=400;w.fly=false;w.tool='platform';expeditionPlace(s,{x:20,y:400});assert.ok(expeditionCell(w,'forest',0,10).platform);expeditionTick(s,.05);assert.equal(w.y,400);w.tool='remove';expeditionPlace(s,{x:20,y:400});for(let i=0;i<5;i++)expeditionTick(s,.05);assert.ok(w.y>400);w.tool='ladder';expeditionPlace(s,{x:100,y:500});assert.ok(expeditionCell(w,'forest',2,12).climb);const copy=normalizeExpeditions(JSON.parse(JSON.stringify(s)));assert.equal(copy.worlds.forest.blocks['2,12'],'ladder');});
test('optional mission goals, safe profile recovery and all native menus retain bounded controls',()=>{const s=normalizeExpeditions({seed:3,active:'bad',worlds:{forest:{x:NaN,dug:['bad'],blocks:{bad:'block'},plots:{bad:{seed:'bean'}}}}});assert.equal(s.active,null);assert.equal(s.worlds.forest.dug.length,0);for(const mode of Object.keys(expeditionModes)){expeditionEnter(s,mode);const w=s.worlds[mode];for(const route of ['home','mission','options','gear','build','bands:0','bands:1','last','farm-help','plot','seeds:0']){const v=expeditionView(s,route,{plants:[{id:'bean',name:'Bean'}]});assert.ok(v.actions.length<=5,mode+route);assert.ok(v.text.length<400);}const camp=expeditionChunkItems(w,mode,0).find(i=>i.type==='camp');w.mission=2;expeditionInteract(s,camp);assert.equal(w.mission,3);expeditionAction(s,{type:'repeat'});assert.equal(w.mission,0);assert.ok(expeditionJournal(s,'adventures').every(e=>Object.hasOwn(expeditionModes,e.expeditionMode)));}const saved=normalizeExpeditions(JSON.parse(JSON.stringify(s)));assert.equal(saved.active,s.active);});
test('one-tap mission travel continuously reaches orbit, abyss and mantle across generated layers',()=>{for(const mode of ['sky','ocean','cave']){const s=normalizeExpeditions({seed:2063});expeditionEnter(s,mode);let g=expeditionGoal(s);expeditionTravel(s,g.point,{item:g.item});const first=run(s);assert.ok(first.r.arrived,mode);expeditionInteract(s,g.item);assert.equal(s.worlds[mode].mission,1);expeditionAction(s,{type:'goal'});run(s);assert.equal(s.worlds[mode].mission,2,mode);const w=s.worlds[mode];assert.ok(w.bands.length>=3,mode);if(mode==='cave')assert.ok(w.dug.length>100);}});
